// spec: specs/seo-robots-sitemap.md (1.1–1.3) · кейсы: .qa/tests/seo-robots-sitemap/ROBOTS-01..03
// #359741: /guides больше не публичная (гайды только у админа) — в тесте 3 проверяется Disallow: /guides и отсутствие в sitemap.
// seed: tests/seed.spec.ts (гость) · прод: только GET через API request, без браузера.
import { test, expect } from '@playwright/test';
import { ORIGIN, BOTS, BLOCKED_PATHS, readRobots, readSitemap, isAllowed } from './robots-sitemap.helpers';

test.describe('robots.txt', () => {
  test('robots.txt: 200 text/plain, Sitemap указывает на рабочий https://www.biz4sale.co.il/sitemap.xml #d777c9 @desktop @prod-safe', async ({ request }) => {
    const { ctype, robots } = await readRobots(request);
    expect(ctype, 'content-type').toContain('text/plain');
    expect(robots.sitemaps, 'строки Sitemap:').toEqual([`${ORIGIN}/sitemap.xml`]);

    const res = await request.get(robots.sitemaps[0]);
    expect(res.status(), 'ответ sitemap').toBe(200);
    const body = await res.text();
    expect(body.trimStart().toLowerCase().startsWith('<!doctype html'), 'sitemap — не HTML-шелл').toBe(false);
    expect(body, 'sitemap — urlset или sitemapindex').toMatch(/<urlset|<sitemapindex/);
  });

  test('robots.txt: приватные и служебные разделы закрыты Disallow для всех ботов, включая AI #d777c9 @desktop @prod-safe', async ({ request }) => {
    const { robots } = await readRobots(request);
    const disallowLines = robots.text.split(/\r?\n/).map((l) => l.trim()).filter((l) => /^disallow\s*:/i.test(l)).map((l) => l.replace(/^disallow\s*:\s*/i, ''));
    const missing = BLOCKED_PATHS.filter((p) => !disallowLines.includes(p));
    expect(missing, 'пути без строки Disallow').toEqual([]);

    const extra = ['/qa/payments', '/payment/success', '/payment/error', '/addbusiness?id=QA-AUTO-check', '/admin/users', '/api/x'];
    const open: string[] = [];
    for (const bot of BOTS) {
      for (const p of [...BLOCKED_PATHS, ...extra]) if (isAllowed(robots, bot, p)) open.push(`${bot} ${p}`);
    }
    expect(open, 'бот + путь, которые должны быть закрыты, но открыты').toEqual([]);
  });

  test('robots.txt: публичные страницы и каждый URL из sitemap разрешены для всех ботов, /guides закрыта #d777c9 #359741 @desktop @prod-safe', async ({ request }) => {
    const { robots } = await readRobots(request);
    expect(robots.text, 'Allow: /').toMatch(/^\s*Allow:\s*\/\s*$/im);
    const agents = robots.groups.flatMap((g) => g.agents);
    for (const bot of BOTS.filter((b) => b !== '*')) expect(agents, `User-agent ${bot}`).toContain(bot.toLowerCase());

    const sm = await readSitemap(request);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);
    const fixed = [
      '/', '/search', '/packages', '/calculator', '/buyerlistings', '/accessibility', '/privacy',
      '/privacy-policy', '/terms', '/terms-of-use', '/faq.html', '/llms.txt', '/sitemap.xml',
      `/b/${sm.listingIds[0].slice(0, 8)}`,
    ];
    const fromSitemap = sm.locs.map((l) => { const u = new URL(l); return u.pathname + u.search; });
    const closed: string[] = [];
    for (const bot of BOTS) {
      for (const p of [...fixed, ...fromSitemap]) if (!isAllowed(robots, bot, p)) closed.push(`${bot} ${p}`);
    }
    expect(closed, 'бот + публичный путь под Disallow').toEqual([]);

    // #359741: гайды скрыты — /guides не в sitemap и закрыта для каждого бота.
    expect(fromSitemap.filter((p) => /^\/guides/i.test(p)), '/guides в sitemap').toEqual([]);
    const disallowLines = robots.text.split(/\r?\n/).map((l) => l.trim()).filter((l) => /^disallow\s*:/i.test(l)).map((l) => l.replace(/^disallow\s*:\s*/i, ''));
    expect(disallowLines, 'строка Disallow: /guides').toContain('/guides');
    const openGuides = BOTS.filter((bot) => isAllowed(robots, bot, '/guides'));
    expect(openGuides, 'боты, которым /guides открыта').toEqual([]);
  });
});
